:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #101b2a;
  color: #f4f2df;
  --navy: #101b2a;
  --panel: #1d3041;
  --tile: #284253;
  --cream: #f4f2df;
  --mint: #8de0b0;
  --orange: #ffb45e;
}
* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background-image: radial-gradient(#31465a 1px, transparent 1px);
  background-size: 18px 18px;
}
button { font: inherit; }
.board {
  width: min(100%, 920px);
  padding: clamp(20px, 5vw, 42px);
  border: 2px solid #486176;
  border-radius: 18px;
  background: var(--navy);
  box-shadow: 0 10px 0 #09111c, 0 24px 70px #07101b99;
}
.heading { text-align: center; margin-bottom: 32px; }
.eyebrow { margin: 0 0 8px; color: var(--mint); font-size: .8rem; font-weight: 800; letter-spacing: .18em; }
h1 { margin: 0; font-size: clamp(2rem, 7vw, 3.4rem); line-height: 1.05; letter-spacing: -.04em; }
.subtitle { margin: 12px 0 0; color: #bcc9d1; }
h2 { margin: 0; font-size: 1.15rem; }
.sheet-section { padding: 20px; border-radius: 12px; background: var(--panel); }
.sheet-section h2 { margin-bottom: 14px; }
.sheet-scroll { overflow-x: auto; border-radius: 6px; }
.score-grid { display: grid; grid-template-columns: repeat(9, minmax(54px, 1fr)) minmax(74px, 1.25fr); gap: 5px; min-width: 610px; }
.frame { min-height: 105px; overflow: hidden; border: 1px solid #557083; border-radius: 5px; background: var(--tile); }
.frame-head { padding: 5px 7px; color: #c5d1d5; font-size: .75rem; font-weight: 700; }
.rolls { display: flex; height: 33px; border-top: 1px solid #557083; border-bottom: 1px solid #557083; }
.roll { flex: 1; display: grid; place-items: center; border-right: 1px solid #557083; font-weight: 800; color: var(--orange); }
.roll:last-child { border-right: 0; }
.frame-total { display: block; padding: 8px 6px; text-align: right; font-size: 1.15rem; font-weight: 800; }
.total-line { display: flex; align-items: center; justify-content: space-between; margin: 18px 2px 0; color: #c5d1d5; font-size: .82rem; font-weight: 800; letter-spacing: .12em; }
#final-score { color: var(--mint); font-size: 2rem; letter-spacing: 0; }
.controls { margin-top: 28px; }
.control-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.control-heading p { margin: 6px 0 0; color: #bcc9d1; }
.reset, .pin-button { color: var(--cream); border: 1px solid #557083; border-radius: 8px; background: var(--panel); cursor: pointer; transition: transform .12s, background .12s, border-color .12s; }
.reset { padding: 10px 14px; font-weight: 700; }
.pin-buttons { display: grid; grid-template-columns: repeat(6, minmax(40px, 1fr)); gap: 8px; margin-top: 18px; }
.pin-button { min-height: 54px; font-size: 1.1rem; font-weight: 800; }
.pin-button:hover, .reset:hover { background: #345165; border-color: var(--mint); }
.pin-button:active, .reset:active { transform: translateY(2px); }
.pin-button:focus-visible, .reset:focus-visible, .sheet-scroll:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
.pin-button:disabled { cursor: not-allowed; opacity: .42; }
.status { min-height: 1.5em; margin: 14px 0 0; color: var(--mint); font-weight: 700; }
footer { margin-top: 26px; color: #93a8b5; text-align: center; font-size: .75rem; font-weight: 700; letter-spacing: .14em; }
footer span { padding: 0 8px; color: var(--orange); }
@media (max-width: 480px) {
  body { padding: 16px 10px; }
  .board { padding: 20px 14px; }
  .sheet-section { padding: 14px 10px; }
  .control-heading { align-items: flex-start; }
  .reset { padding: 9px 10px; }
  .pin-buttons { grid-template-columns: repeat(4, 1fr); }
}

const sheet = document.querySelector('#score-sheet');
const buttons = document.querySelector('#pin-buttons');
const status = document.querySelector('#status');
const finalScore = document.querySelector('#final-score');
const hint = document.querySelector('#turn-hint');
let rolls = [];

for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'pin-button';
  button.textContent = String(pins);
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'}`);
  button.addEventListener('click', () => enterRoll(pins));
  buttons.append(button);
}
document.querySelector('#reset').addEventListener('click', resetGame);

function framesFromRolls(input) {
  const frames = [];
  let i = 0;
  for (let f = 0; f < 10; f++) {
    if (f === 9) {
      frames.push(input.slice(i, i + 3));
      break;
    }
    if (input[i] === 10) { frames.push([10]); i++; }
    else if (input.length > i + 1) { frames.push(input.slice(i, i + 2)); i += 2; }
    else { frames.push(input.slice(i)); break; }
  }
  return frames;
}
function rollMark(frame, index, frameIndex) {
  const n = frame[index];
  if (n === undefined) return '';
  if (frameIndex < 9 && index === 0 && n === 10) return 'X';
  if (frameIndex < 9 && index === 1 && frame[0] + n === 10) return '/';
  if (frameIndex === 9 && index === 1 && frame[0] !== 10 && frame[0] + n === 10) return '/';
  if (frameIndex === 9 && index === 2 && frame[0] === 10 && frame[1] + n === 10) return '/';
  return n === 0 ? '−' : String(n);
}
function scoreFrames(frames) {
  const flat = rolls;
  let cursor = 0;
  let running = 0;
  return frames.map((frame, index) => {
    let score = null;
    if (index < 9 && frame.length) {
      if (frame[0] === 10) {
        if (flat.length >= cursor + 3) score = 10 + flat[cursor + 1] + flat[cursor + 2];
        cursor++;
      } else if (frame.length === 2) {
        score = frame[0] + frame[1];
        if (score === 10) { if (flat.length > cursor + 2) score += flat[cursor + 2]; }
        cursor += 2;
      } else cursor += frame.length;
    } else if (index === 9 && frame.length >= 2) score = frame.reduce((a, b) => a + b, 0);
    if (score !== null) running += score;
    return { frame, total: score === null ? null : running };
  });
}
function render() {
  const frames = framesFromRolls(rolls);
  const scored = scoreFrames(frames);
  sheet.replaceChildren();
  scored.forEach(({ frame, total }, i) => {
    const cell = document.createElement('div');
    cell.className = 'frame';
    const head = document.createElement('div');
    head.className = 'frame-head';
    head.textContent = `FRAME ${i + 1}`;
    const row = document.createElement('div');
    row.className = 'rolls';
    const slots = i === 9 ? 3 : 2;
    for (let r = 0; r < slots; r++) {
      const slot = document.createElement('span');
      slot.className = 'roll';
      slot.textContent = rollMark(frame, r, i);
      row.append(slot);
    }
    const sum = document.createElement('strong');
    sum.className = 'frame-total';
    sum.textContent = total === null ? '—' : String(total);
    cell.append(head, row, sum);
    sheet.append(cell);
  });
  const tenth = frames[9];
  const tenthComplete = tenth.length >= 2 && (tenth[0] !== 10 && tenth[0] + tenth[1] < 10 || tenth.length === 3);
  const gameOver = tenthComplete;
  finalScore.value = gameOver ? String(scored[9].total) : '—';
  const current = frames.findIndex((frame, i) => i < 9 && (frame.length === 0 || (frame[0] !== 10 && frame.length < 2)));
  const frameNo = current < 0 ? 10 : current + 1;
  const rollNo = current < 0 ? tenth.length + 1 : frames[current][0] === 10 ? 2 : frames[current].length + 1;
  const max = current < 0 && tenth.length ? (tenth[0] === 10 || tenth[0] + (tenth[1] || 0) === 10 ? 10 : 10 - tenth[0] - tenth[1]) :
    current >= 0 && frames[current].length === 1 && frames[current][0] !== 10 ? 10 - frames[current][0] : 10;
  [...buttons.children].forEach((button, value) => { button.disabled = gameOver || value > max; });
  status.textContent = gameOver ? `Game complete · ${scored[9].total} points` : `Frame ${frameNo} · Roll ${rollNo}`;
  hint.textContent = gameOver ? 'Start a new game to bowl again.' : `Choose 0–${max} pins for this roll.`;
}
function enterRoll(pins) {
  const frames = framesFromRolls(rolls);
  const frame = frames.find((f, i) => i < 9 && (f.length === 0 || (f[0] !== 10 && f.length < 2)));
  const tenth = frames[9] || [];
  const max = frame && frame.length === 1 ? 10 - frame[0] :
    !frame && tenth.length === 1 && tenth[0] !== 10 ? 10 - tenth[0] :
    !frame && tenth.length === 2 && tenth[0] !== 10 && tenth[0] + tenth[1] < 10 ? 0 : 10;
  if (pins > max || rolls.length >= 21) return;
  rolls.push(pins);
  render();
}
function resetGame() { rolls = []; render(); buttons.children[0].focus(); }
render();
